const item = $input.first();

// Helper: safe BigInt conversion
const BI = (v) => BigInt(v || 0);


// ===============================
// 1. Calculate remaining balance
// ===============================
const balance =
  BI(item.json['Deposited Fund']) -
  BI(item.json.Fee) -
  BI(item.json['Tip to Seller']) -
  BI(item.json['Buyer Withdrawal']) -
  BI(item.json['Payment to Seller']) -
  BI(item.json['Refund to Buyer']);


// ===============================
// 2. Calculate remaining escrow
// ===============================
const escrowRaw =
  BI(item.json['Escrow Fund']) -
  BI(item.json['Payment to Seller']) -
  BI(item.json['Refund to Buyer']);

const escrowWei = escrowRaw > 0n ? escrowRaw : 0n;


// ===============================
// 3. Convert remaining Escrow balance to Ether
// ===============================

const escrowEth = escrowWei > 0n ? (Number(escrowWei) / 1e18) : "0";

// ===============================
// 4. Request Date if a request is pending
// ===============================
const requestDate = item.json['Refund Request Time'] || item.json['Payment Request Time'];

// ===============================
// 5. Return (BigInt → string)
// ===============================
return {
  balance,
  escrowEth, 
  requestDate
};

