const caseInfo = $('Get Case Info1').first().json;
const sender_email = $('Case ID in Subject').first().json.sender_email; 

const role = (sender_email === caseInfo['Seller Email'] ? 'Seller' : 'Buyer'); 

// 1. Capture original and standardize line endings (\r\n to \n)
const originalBody = item.text || item.textPlain || "";
let body = originalBody.replace(/\r\n/g, '\n');

// PHASE 1: The "Hard" Markers (High Confidence Split Points)
// These definitively mark the start of an old thread or platform boundary.
const hardMarkers = [
  /-- PLEASE TYPE YOUR RESPONSE ABOVE THIS LINE --/i,
  /^[> ]*On .* at .* wrote:/im,
  /^[> ]*On (?:Mon|Tue|Wed|Thu|Fri|Sat|Sun).* wrote:/im,
  /^[> ]*From: .*/im,
  /^[> ]*_{3,}/im,       // Standard Outlook horizontal line (___)
  /^-- \n/im             // Standard RFC-compliant signature delimiter
];

let cutIndex = body.length;

// Find the earliest Hard Marker
for (const marker of hardMarkers) {
  const match = body.match(marker);
  if (match && match.index < cutIndex) {
    cutIndex = match.index;
  }
}

// Execute the hard cut
let processedBody = body.substring(0, cutIndex).trim();


// PHASE 2: The "Soft" Signatures (Bottom-Up Trim)
// We only remove these if they are anchored to the absolute END of the remaining text.
// This prevents cutting the email if someone says "Thanks for your help" in paragraph two.
const softMarkers = [
  /(?:Best|Kind|Warm)?\s*Regards,?\s*\n[\s\S]*$/i,
  /Thanks,?\s*\n[\s\S]*$/i,
  /Sincerely,?\s*\n[\s\S]*$/i,
  /Sent from my (iPhone|Android|Samsung)[\s\S]*$/i
];

for (const marker of softMarkers) {
  // Replace only if it matches at the end of the text
  processedBody = processedBody.replace(marker, '').trim();
}


// PHASE 3: Legal Fluff Scrub
const fluffPatterns = [
  /CONFIDENTIALITY NOTICE:[\s\S]*/gi,
  /DISCLAIMER:[\s\S]*/gi,
  /This e-mail message and its attachments[\s\S]*/gi
];

for (const pattern of fluffPatterns) {
  processedBody = processedBody.replace(pattern, "").trim();
}


// THE SAFETY NET
// If the parsed message is suspiciously short (e.g., empty or just whitespace),
// we abort the cut and use the original body so evidence is never lost.
let finalMessage = processedBody;
if (processedBody.length < 5) {
  finalMessage = originalBody.trim(); 
}


return [{
  case_id: caseInfo['Case ID'],
  role: role,
  sender_email: sender_email,
  timestamp: item.date || new Date().toISOString(),
  message: finalMessage,
  _debug_original: originalBody // Hidden field: highly recommended for audits!
}];
